import { useState } from 'react';
import { useDispatch } from 'react-redux';
import { login } from '../../store/slices/authSlice';
import { DEMO_USER } from '../../constants/models';
import { useTheme } from '../../hooks/useTheme';

export default function LoginPage() {
  const dispatch = useDispatch();
  const { dark, bgHex, cardHex, textHex, mutedHex, borderHex, inputHex } = useTheme();
  const [email, setEmail]     = useState('');
  const [password, setPassword] = useState('');
  const [error, setError]     = useState('');
  const [loading, setLoading] = useState(false);
  const [showPass, setShowPass] = useState(false);
  const accent = '#6366f1';
  const pageBg = dark
    ? 'radial-gradient(circle at 50% 18%, rgba(99,102,241,0.18), transparent 32%), radial-gradient(circle at 18% 78%, rgba(139,92,246,0.12), transparent 30%), #0A0A0A'
    : bgHex;
  const panelBg = dark ? 'rgba(52, 52, 52, 0.46)' : cardHex;
  const panelBorder = dark ? 'rgba(255, 255, 255, 0.16)' : borderHex;
  const fieldBg = dark ? 'rgba(255, 255, 255, 0.08)' : inputHex;
  const fieldBorder = dark ? 'rgba(255, 255, 255, 0.14)' : borderHex;

  const handle = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    await new Promise((r) => setTimeout(r, 700));
    if (email === DEMO_USER.email && password === DEMO_USER.password) {
      dispatch(login({ email, name: DEMO_USER.name }));
    } else {
      setError(`Invalid credentials. Try ${DEMO_USER.email} / ${DEMO_USER.password}`);
    }
    setLoading(false);
  };

  return (
    <div style={{ minHeight: '100vh', background: pageBg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: "'DM Sans', sans-serif", padding: '1rem' }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        @keyframes fadeIn { from{opacity:0;transform:translateY(12px)} to{opacity:1;transform:translateY(0)} }
        @keyframes spin { to { transform: rotate(360deg); } }
        .li { width:100%; padding:11px 14px; border-radius:10px; border:1.5px solid ${fieldBorder}; background:${fieldBg}; color:${textHex}; font-size:14.5px; font-family:inherit; outline:none; transition:border 0.2s, background 0.2s; }
        .li:focus { border-color:${accent}; }
        .li::placeholder { color:${mutedHex}; }
        .lb { width:100%; padding:12px; border-radius:10px; background:${accent}; color:#fff; font-size:15px; font-weight:600; border:none; cursor:pointer; font-family:inherit; transition:opacity 0.2s; }
        .lb:hover:not(:disabled) { opacity:0.88; }
        .lb:disabled { opacity:0.6; cursor:default; }
      `}</style>
      <div style={{
        width: '100%',
        maxWidth: 420,
        background: panelBg,
        borderRadius: 20,
        border: `1.5px solid ${panelBorder}`,
        padding: '2.5rem 2rem',
        animation: 'fadeIn 0.4s ease',
        backdropFilter: dark ? 'blur(22px) saturate(150%)' : 'none',
        WebkitBackdropFilter: dark ? 'blur(22px) saturate(150%)' : 'none',
        boxShadow: dark ? '0 24px 80px rgba(0,0,0,0.58), inset 0 1px 0 rgba(255,255,255,0.08)' : 'none',
      }}>
        {/* Logo */}
        <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
          <div style={{ width: 56, height: 56, borderRadius: 16, background: 'linear-gradient(135deg,#6366f1,#8b5cf6)', margin: '0 auto 1rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <svg width="28" height="28" viewBox="0 0 28 28" fill="none"><circle cx="14" cy="14" r="12" stroke="white" strokeWidth="2"/><circle cx="10" cy="12.5" r="2" fill="white"/><circle cx="18" cy="12.5" r="2" fill="white"/><path d="M10 18c1.2 1.5 6.8 1.5 8 0" stroke="white" strokeWidth="1.5" strokeLinecap="round"/></svg>
          </div>
          <h1 style={{ fontSize: 24, fontWeight: 700, color: textHex, fontFamily: "'Space Grotesk'" }}>Welcome to HelixtaAI</h1>
          <p style={{ fontSize: 14, color: mutedHex, marginTop: 6 }}>Sign in to start chatting</p>
        </div>
        {/* Form */}
        <form onSubmit={handle} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <div>
            <label style={{ fontSize: 13, fontWeight: 500, color: mutedHex, display: 'block', marginBottom: 6 }}>Email</label>
            <input className="li" type="email" placeholder={DEMO_USER.email} value={email} onChange={(e) => setEmail(e.target.value)} required/>
          </div>
          <div>
            <label style={{ fontSize: 13, fontWeight: 500, color: mutedHex, display: 'block', marginBottom: 6 }}>Password</label>
            <div style={{ position: 'relative' }}>
              <input className="li" type={showPass ? 'text' : 'password'} placeholder="••••••••" value={password} onChange={(e) => setPassword(e.target.value)} required style={{ paddingRight: 44 }}/>
              <button type="button" onClick={() => setShowPass((p) => !p)} style={{ position: 'absolute', right: 12, top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', cursor: 'pointer', color: mutedHex, padding: 2 }}>
                {showPass
                  ? <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
                  : <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                }
              </button>
            </div>
          </div>
          {error && <p style={{ color: '#f87171', fontSize: 13, background: '#450a0a22', borderRadius: 8, padding: '8px 12px' }}>{error}</p>}
          <button className="lb" type="submit" disabled={loading} style={{ marginTop: 4 }}>
            {loading ? (
              <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
                <span style={{ width: 16, height: 16, border: '2px solid rgba(255,255,255,0.4)', borderTopColor: '#fff', borderRadius: '50%', animation: 'spin 0.7s linear infinite', display: 'inline-block' }}/>
                Signing in...
              </span>
            ) : 'Sign in'}
          </button>
        </form>
        <p style={{ textAlign: 'center', fontSize: 13, color: mutedHex, marginTop: '1.25rem' }}>
          Demo: <span style={{ color: accent }}>{DEMO_USER.email}</span> / <span style={{ color: accent }}>{DEMO_USER.password}</span>
        </p>
      </div>
    </div>
  );
}
